/**
 * 将 V2-01 / V2-08 的 ``step_status`` / ``execution_panel`` 转为执行面板卡片状态与摘要行。
 * 摘要数值由后端 ``execution_panel`` 提供，前端不做指标换算。
 */

const IDLE = { enum: 'idle', price: 'idle', portfolio: 'idle', decision: 'idle' };
const RUN_STEP_NAMES = new Set(['enum', 'price', 'portfolio']);
const DOWNSTREAM_STEPS = {
  enum: ['price', 'portfolio'],
  price: ['portfolio'],
  portfolio: [],
};

/**
 * 复写上游步时把下游圆圈打回 idle（D18）。当前步标 running。
 * @param {object} prev
 * @param {string} target
 */
export function resetDownstreamStepStatus(prev, target) {
  const next = { ...(prev && typeof prev === 'object' ? prev : IDLE) };
  const key = String(target || '').trim();
  if (!RUN_STEP_NAMES.has(key)) return next;
  next[key] = 'running';
  (DOWNSTREAM_STEPS[key] || []).forEach((ds) => {
    next[ds] = 'idle';
  });
  return next;
}

/**
 * V2-05 POST ``steps[]`` → 执行面板 stepStatus。只更新计划内步骤，其余保留 ``prev``（依赖链由后端规划）。
 * @param {object} prev
 * @param {object[]} planSteps
 */
export function stepStatusFromRunPlanSteps(planSteps, prev = IDLE) {
  const next = { ...prev };
  if (!Array.isArray(planSteps) || planSteps.length === 0) return next;
  let runningTarget = '';
  planSteps.forEach((row, idx) => {
    const nm = String(row?.step_name || '').trim();
    if (!RUN_STEP_NAMES.has(nm)) return;
    const backendSt = String(row?.status || '').toLowerCase();
    if (backendSt === 'completed') next[nm] = 'done';
    else if (backendSt === 'running') next[nm] = 'running';
    else if (backendSt === 'failed') next[nm] = 'failed';
    else if (backendSt === 'pending') next[nm] = 'pending';
    else next[nm] = idx === 0 ? 'running' : 'pending';
    if (next[nm] === 'running' && !runningTarget) runningTarget = nm;
  });
  if (runningTarget) {
    (DOWNSTREAM_STEPS[runningTarget] || []).forEach((ds) => {
      next[ds] = 'idle';
    });
  }
  return next;
}

/**
 * V2-06b ``step_status_merge`` → 合并进当前 stepStatus（轮询唯一来源，不推断依赖）。
 * @param {object} prev
 * @param {object|null|undefined} progressMerge
 */
export function mergeStepStatusFromRunProgress(prev, progressMerge) {
  if (!progressMerge || typeof progressMerge !== 'object') return prev;
  const next = { ...prev };
  Object.keys(progressMerge).forEach((key) => {
    if (!RUN_STEP_NAMES.has(key)) return;
    const incoming = String(progressMerge[key] || '').trim() || 'idle';
    const current = String(next[key] || 'idle');
    // 轮询空闲态不能盖掉已完成：否则切步/错序 poll 会把圆圈打回未运行。
    if (incoming === 'idle' && current === 'done') return;
    next[key] = incoming;
  });
  return next;
}

/**
 * 快照 hydration 与当前 stepStatus 合并。
 * 始终以磁盘快照为准（含同 vid 上 D18 把下游打回 idle）。
 */
export function mergeHydratedStepStatus(_prevStatus, hydratedStatus, _opts = {}) {
  const hydrated = hydratedStatus && typeof hydratedStatus === 'object'
    ? hydratedStatus
    : { ...IDLE };
  return {
    enum: String(hydrated.enum || 'idle'),
    price: String(hydrated.price || 'idle'),
    portfolio: String(hydrated.portfolio || 'idle'),
    decision: String(hydrated.decision || 'idle'),
  };
}

function slotDone(entry) {
  if (!entry || typeof entry !== 'object') return false;
  return entry.done === true;
}

/**
 * @param {object|null|undefined} apiStepStatus BFF：``enum`` / ``price_factor`` / ``portfolio`` → ``{ done: boolean }``
 * @returns {{ enum: string, price: string, portfolio: string, decision: string }}
 */
export function mapWorkbenchStepStatusToExecutionCards(apiStepStatus) {
  if (!apiStepStatus || typeof apiStepStatus !== 'object') {
    return { ...IDLE };
  }
  return {
    enum: slotDone(apiStepStatus.enum) ? 'done' : 'idle',
    price: (slotDone(apiStepStatus.price_factor) || slotDone(apiStepStatus.price))
      ? 'done'
      : 'idle',
    portfolio: slotDone(apiStepStatus.portfolio) ? 'done' : 'idle',
    decision: slotDone(apiStepStatus.decision) ? 'done' : 'idle',
  };
}

/**
 * 从 BFF ``execution_panel`` 读取执行面板三行摘要。
 * @param {object|null|undefined} executionPanel
 * @returns {{ enum: object|null, price: object|null, portfolio: object|null }}
 */
export function buildExecutionResultFromExecutionPanel(executionPanel) {
  const empty = { enum: null, price: null, portfolio: null };
  if (!executionPanel || typeof executionPanel !== 'object') {
    return empty;
  }
  return {
    enum: executionPanel.enum ?? null,
    price: executionPanel.price ?? null,
    portfolio: executionPanel.portfolio ?? null,
  };
}

/**
 * @param {string} strategyName
 * @param {{ versionId?: string, step_status?: object|null, execution_panel?: object|null }} snapshot
 */
export function buildWorkbenchExecutionHydrationFromSnapshot(strategyName, snapshot) {
  const wbVer = String(snapshot?.versionId || '').trim();
  const stepCards = mapWorkbenchStepStatusToExecutionCards(snapshot?.step_status);
  const execResult = buildExecutionResultFromExecutionPanel(snapshot?.execution_panel);
  return {
    key: `${strategyName}:${wbVer || 'none'}`,
    stepStatus: stepCards,
    result: execResult,
    lastCompletedWorkbenchVersionId: wbVer,
  };
}
