import { formatReportChartDateLabel } from './reportDateFormat';
import {
  REPORT_MARKER_PIN_DOWN,
  REPORT_MARKER_PIN_OFFSET_DOWN,
  REPORT_MARKER_PIN_OFFSET_UP,
  REPORT_MARKER_PIN_SIZE,
  REPORT_MARKER_PIN_UP,
  reportMarkerPinStyle,
} from './reportChartMarkers';
import {
  REPORT_CHART_AXIS_LABEL_SM,
  REPORT_CHART_AXIS_LINE,
  REPORT_CHART_SPLIT_LINE,
  REPORT_CHART_TOOLTIP,
} from './reportChartsTheme';

const MARKER_COLORS = {
  buy: '#00E5FF',
  sell: '#C62828',
  opportunity: '#00E5FF',
  /** 与 K 线阳线红区分：暖橙表胜 */
  target_win: '#FF9100',
  /** 与 K 线阴线绿区分：紫罗兰表负 */
  target_loss: '#B388FF',
};

/** A 股习惯：阳线红、阴线绿（close vs open） */
const CANDLE_UP_COLOR = '#FF4D67';
const CANDLE_DOWN_COLOR = '#00D9A5';

/** Pin 尖端指向 K 线：买入在下方尖朝上，目标在上方尖朝下；path 与挂载位置对调 */
const MARKER_BELOW_CANDLE_SYMBOL = REPORT_MARKER_PIN_UP;
const MARKER_ABOVE_CANDLE_SYMBOL = REPORT_MARKER_PIN_DOWN;
const UP_MARKER_SIZE = REPORT_MARKER_PIN_SIZE;
const DOWN_MARKER_SIZE = REPORT_MARKER_PIN_SIZE;
const UP_MARKER_OFFSET_Y = REPORT_MARKER_PIN_OFFSET_UP;
const DOWN_MARKER_OFFSET_Y = REPORT_MARKER_PIN_OFFSET_DOWN;

function buildMarkerItemStyle(color, shadowRgb) {
  return reportMarkerPinStyle(color, shadowRgb);
}

function buildCyanUpArrowStyle() {
  return buildMarkerItemStyle(MARKER_COLORS.opportunity, '0, 229, 255');
}

function buildTargetArrowStyle(type) {
  const color = type === 'target_win' ? MARKER_COLORS.target_win : MARKER_COLORS.target_loss;
  const shadow = type === 'target_win' ? '255, 145, 0' : '179, 136, 255';
  return buildMarkerItemStyle(color, shadow);
}

const MARKER_LEGEND_DEFS = {
  opportunity: { label: '机会', symbol: MARKER_BELOW_CANDLE_SYMBOL, style: buildCyanUpArrowStyle },
  buy: { label: '买入', symbol: MARKER_BELOW_CANDLE_SYMBOL, style: buildCyanUpArrowStyle },
  target_win: { label: '目标胜', symbol: MARKER_ABOVE_CANDLE_SYMBOL, style: () => buildTargetArrowStyle('target_win') },
  target_loss: { label: '目标负', symbol: MARKER_ABOVE_CANDLE_SYMBOL, style: () => buildTargetArrowStyle('target_loss') },
};

function markerYValue(item, candleByDate) {
  const date = String(item?.date || '').trim();
  const bar = candleByDate?.get(date);
  const type = String(item?.type || '').trim();
  if (type === 'opportunity' || type === 'buy') {
    const low = Number(bar?.low);
    return Number.isFinite(low) ? low : null;
  }
  if (type === 'target_win' || type === 'target_loss') {
    const high = Number(bar?.high);
    return Number.isFinite(high) ? high : null;
  }
  const px = Number(item?.price);
  return Number.isFinite(px) ? px : null;
}

function uniqueDetailParts(values) {
  const out = [];
  values.forEach((value) => {
    if (value == null || value === '') return;
    const text = String(value).trim();
    if (text && !out.includes(text)) out.push(text);
  });
  return out;
}

function mergeMarkerDetail(base, extra) {
  const a = base && typeof base === 'object' ? { ...base } : {};
  const b = extra && typeof extra === 'object' ? extra : {};
  const names = uniqueDetailParts([a.goal_name, b.goal_name]);
  if (names.length) a.goal_name = names.join('、');
  const ra = Number(a.exit_ratio);
  const rb = Number(b.exit_ratio);
  if (Number.isFinite(ra) && ra > 0 && Number.isFinite(rb) && rb > 0) {
    a.exit_ratio = Math.min(1, ra + rb);
  } else if (!(Number.isFinite(ra) && ra > 0) && Number.isFinite(rb) && rb > 0) {
    a.exit_ratio = rb;
  }
  const rois = uniqueDetailParts([
    typeof a.roi === 'number' ? fmtPrice(a.roi) : a.roi,
    typeof b.roi === 'number' ? fmtPrice(b.roi) : b.roi,
  ]);
  if (rois.length) a.roi = rois.join('、');
  if (b.exit_price != null && b.exit_price !== '') a.exit_price = b.exit_price;
  const reasons = uniqueDetailParts([a.exit_reason, b.exit_reason]);
  if (reasons.length) a.exit_reason = reasons.join('、');
  return a;
}

/** 同日同类型只留一个点（两档同日止盈会叠在一起）。 */
function collapseOverlappingMarkers(markers) {
  const kept = new Map();
  const order = [];
  (markers || []).forEach((item) => {
    const type = String(item?.type || '').trim();
    const date = String(item?.date || '').trim();
    if (!type || !date) return;
    const key = `${type}|${date}`;
    if (!kept.has(key)) {
      const copy = {
        ...item,
        detail: item.detail && typeof item.detail === 'object' ? { ...item.detail } : {},
      };
      kept.set(key, copy);
      order.push(copy);
      return;
    }
    const existing = kept.get(key);
    existing.detail = mergeMarkerDetail(existing.detail, item.detail);
  });
  return order;
}

/** 真实 scatter 点（不要空 data 图例系列：axis tooltip 滑过会 getRawIndex 崩）。 */
function buildMarkerScatterSeries(markers, candleByDate) {
  const byType = new Map();
  collapseOverlappingMarkers(markers).forEach((item) => {
    const type = String(item?.type || '').trim();
    const def = MARKER_LEGEND_DEFS[type];
    const date = String(item?.date || '').trim();
    const y = markerYValue(item, candleByDate);
    if (!def || !date || y == null) return;
    if (!byType.has(type)) byType.set(type, []);
    const isTarget = type === 'target_win' || type === 'target_loss';
    byType.get(type).push({
      value: [date, y],
      symbolOffset: isTarget ? [0, DOWN_MARKER_OFFSET_Y] : [0, UP_MARKER_OFFSET_Y],
      _markerMeta: item,
    });
  });
  return [...byType.entries()].map(([type, data]) => {
    const def = MARKER_LEGEND_DEFS[type];
    const isTarget = type === 'target_win' || type === 'target_loss';
    return {
      name: def.label,
      type: 'scatter',
      xAxisIndex: 0,
      yAxisIndex: 0,
      data,
      symbol: def.symbol,
      symbolSize: isTarget ? DOWN_MARKER_SIZE : UP_MARKER_SIZE,
      itemStyle: def.style(),
      tooltip: { show: false },
      legendHoverLink: false,
      clip: false,
      z: 12,
      encode: { x: 0, y: 1 },
    };
  });
}

const DEFAULT_ZOOM_WINDOW = 35;
/** 副图高度 ≈ 主图 K 线区域的 32%（落在 1/4–1/3 区间） */
const PANEL_DIVIDER_COLOR = 'rgba(255, 255, 255, 0.52)';
const DUAL_PANEL_LAYOUT = {
  priceTop: 8,
  priceHeight: 51,
  gap: 3.5,
  oscHeight: 17,
};

function buildDualPanelGrids() {
  const { priceTop, priceHeight, gap, oscHeight } = DUAL_PANEL_LAYOUT;
  const oscTop = priceTop + priceHeight + gap;
  return [
    { left: 44, right: 16, top: `${priceTop}%`, height: `${priceHeight}%` },
    {
      left: 44,
      right: 16,
      top: `${oscTop}%`,
      height: `${oscHeight}%`,
      borderWidth: 2,
      borderColor: PANEL_DIVIDER_COLOR,
      backgroundColor: 'rgba(255, 255, 255, 0.04)',
    },
  ];
}

function buildPanelDividerGraphic() {
  const { priceTop, priceHeight, gap } = DUAL_PANEL_LAYOUT;
  const dividerTop = priceTop + priceHeight + (gap / 2);
  return [{
    type: 'rect',
    left: 44,
    right: 16,
    top: `${dividerTop}%`,
    z: 4,
    silent: true,
    shape: { x: 0, y: -1, width: 4000, height: 2 },
    style: { fill: PANEL_DIVIDER_COLOR },
  }];
}

function fmtPrice(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '—';
  return n.toFixed(2);
}

function fmtIndicator(value) {
  const n = Number(value);
  if (!Number.isFinite(n)) return '—';
  return n.toFixed(2);
}

const MARKER_DETAIL_LABELS = {
  investment_id: '投资 ID',
  opportunity_id: '机会 ID',
  trigger_date: '触发日',
  chart_close: '图上收盘价',
  engine_trigger_price: '引擎记录价',
  entry_date: '入场日',
  entry_price: '入场价',
  exit_date: '出场日',
  exit_price: '出场价',
  lifecycle: '生命周期',
  result: '结果',
  exit_reason: '出场原因',
  goal_name: '目标',
  exit_ratio: '卖出比例',
  roi: '收益率',
};

const MARKER_DETAIL_DATE_KEYS = new Set([
  'trigger_date',
  'entry_date',
  'exit_date',
]);

function formatMarkerDetailValue(key, value) {
  if (MARKER_DETAIL_DATE_KEYS.has(key)) {
    return formatReportChartDateLabel(String(value));
  }
  if (key === 'exit_ratio') {
    const n = Number(value);
    if (!Number.isFinite(n)) return String(value);
    return `${(n * 100).toFixed(n * 100 % 1 === 0 ? 0 : 1)}%`;
  }
  if (typeof value === 'number') return fmtPrice(value);
  return String(value);
}

function formatMarkerTooltip(marker) {
  const lines = [marker.label || marker.type || '标记'];
  const detail = marker.detail && typeof marker.detail === 'object' ? marker.detail : {};
  Object.entries(detail).forEach(([k, v]) => {
    if (v == null || v === '') return;
    const label = MARKER_DETAIL_LABELS[k] || k;
    lines.push(`${label}: ${formatMarkerDetailValue(k, v)}`);
  });
  if (marker.date) lines.unshift(formatReportChartDateLabel(marker.date));
  return lines.filter(Boolean).join('<br/>');
}

function initialZoomRange(length) {
  if (length <= DEFAULT_ZOOM_WINDOW) {
    return { start: 0, end: 100 };
  }
  const start = Math.max(0, 100 - Math.round((DEFAULT_ZOOM_WINDOW / length) * 100));
  return { start, end: 100 };
}

function buildCandleLookup(candles) {
  const byDate = new Map();
  (candles || []).forEach((row) => {
    const date = String(row?.date || '').trim();
    if (date) byDate.set(date, row);
  });
  return byDate;
}

/** 优先用业务 candles（按日期），避免 ECharts 把 dataIndex 塞进 data 首项。 */
function readCandlestickOHLC(param, candleByDate, candleData) {
  if (param?.seriesType !== 'candlestick') return null;

  const dateKey = String(param.axisValue ?? param.name ?? '').trim();
  if (dateKey && candleByDate?.has(dateKey)) {
    const row = candleByDate.get(dateKey);
    const open = Number(row.open);
    const close = Number(row.close);
    const low = Number(row.low);
    const high = Number(row.high);
    if ([open, close, low, high].every(Number.isFinite)) {
      return { open, close, low, high };
    }
  }

  const idx = Number(param.dataIndex);
  if (Number.isInteger(idx) && idx >= 0 && Array.isArray(candleData?.[idx])) {
    const [open, close, low, high] = candleData[idx].map((v) => Number(v));
    if ([open, close, low, high].every(Number.isFinite)) {
      return { open, close, low, high };
    }
  }

  let raw = param.value;
  if (!Array.isArray(raw)) raw = param.data;
  if (!Array.isArray(raw) || raw.length < 4) return null;
  // 部分 ECharts 版本为 [dataIndex, open, close, low, high]
  const nums = (raw.length >= 5 && Number.isInteger(raw[0]) && raw[0] < 100000
    ? raw.slice(1, 5)
    : raw.slice(0, 4)
  ).map((v) => Number(v));
  if (nums.some((v) => !Number.isFinite(v))) return null;
  const [open, close, low, high] = nums;
  return { open, close, low, high };
}

function normalizeCandleRow(item) {
  const open = Number(item.open);
  const close = Number(item.close);
  let low = Number(item.low);
  let high = Number(item.high);
  if (![open, close, low, high].every(Number.isFinite)) return null;
  if (high < low) {
    const tmp = high;
    high = low;
    low = tmp;
  }
  return [open, close, low, high];
}

/** 日期轴、K 线、指标必须同索引；不可单独 filter 蜡烛行否则 tooltip 会串日。 */
function prepareAlignedChartRows(candles, indicatorSeries) {
  const dates = [];
  const candleData = [];
  const validIndexes = [];
  (candles || []).forEach((item, index) => {
    const row = normalizeCandleRow(item);
    if (!row) return;
    validIndexes.push(index);
    dates.push(item.date);
    candleData.push(row);
  });
  const alignedIndicators = (indicatorSeries || []).map((row) => ({
    ...row,
    data: validIndexes.map((i) => {
      const values = Array.isArray(row.data) ? row.data : [];
      return i < values.length ? values[i] : null;
    }),
  }));
  return { dates, candleData, indicatorSeries: alignedIndicators };
}

export function buildStockKlineChartOptionFromPayload(payload) {
  if (!payload || !Array.isArray(payload.candles) || payload.candles.length === 0) return {};
  const {
    dates,
    candleData,
    indicatorSeries,
  } = prepareAlignedChartRows(payload.candles, payload.indicator_series);
  if (!candleData.length) return {};

  const candleByDate = buildCandleLookup(payload.candles);
  const markerSeries = buildMarkerScatterSeries(payload.markers, candleByDate);
  const oscillatorRows = indicatorSeries.filter((row) => row.panel === 'oscillator');
  const overlayRows = indicatorSeries.filter((row) => row.panel !== 'oscillator');
  const hasOscillator = oscillatorRows.length > 0;
  const zoom = initialZoomRange(dates.length);
  const xZoomIndexes = hasOscillator ? [0, 1] : [0];

  const legendItems = [
    'K线',
    ...overlayRows.map((row) => row.label || row.key),
    ...oscillatorRows.map((row) => row.label || row.key),
    ...markerSeries.map((row) => row.name),
  ];

  const overlayLineSeries = overlayRows.map((row) => ({
    name: row.label || row.key,
    type: 'line',
    xAxisIndex: 0,
    yAxisIndex: 0,
    showSymbol: false,
    smooth: false,
    lineStyle: { width: 1.5, color: row.color || undefined },
    itemStyle: { color: row.color || undefined },
    data: Array.isArray(row.data) ? row.data : [],
    connectNulls: false,
  }));

  const oscillatorLineSeries = oscillatorRows.map((row) => ({
    name: row.label || row.key,
    type: 'line',
    xAxisIndex: 1,
    yAxisIndex: 1,
    showSymbol: false,
    smooth: false,
    lineStyle: { width: 1.5, color: row.color || undefined },
    itemStyle: { color: row.color || undefined },
    data: Array.isArray(row.data) ? row.data : [],
    connectNulls: false,
  }));

  const grid = hasOscillator
    ? buildDualPanelGrids()
    : [{ left: 44, right: 16, top: 28, height: '68%' }];

  const xAxis = hasOscillator
    ? [
      {
        type: 'category',
        gridIndex: 0,
        data: dates,
        scale: true,
        boundaryGap: true,
        axisLine: REPORT_CHART_AXIS_LINE,
        axisLabel: { show: false },
      },
      {
        type: 'category',
        gridIndex: 1,
        data: dates,
        scale: true,
        boundaryGap: true,
        axisLine: REPORT_CHART_AXIS_LINE,
        axisLabel: {
          ...REPORT_CHART_AXIS_LABEL_SM,
          formatter: (v) => formatReportChartDateLabel(v),
        },
      },
    ]
    : [{
      type: 'category',
      data: dates,
      scale: true,
      boundaryGap: true,
      axisLine: REPORT_CHART_AXIS_LINE,
      axisLabel: {
        ...REPORT_CHART_AXIS_LABEL_SM,
        formatter: (v) => formatReportChartDateLabel(v),
      },
    }];

  const yAxis = hasOscillator
    ? [
      {
        gridIndex: 0,
        scale: true,
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: {
          ...REPORT_CHART_AXIS_LABEL_SM,
          formatter: (v) => fmtPrice(v),
        },
        splitLine: REPORT_CHART_SPLIT_LINE,
      },
      {
        gridIndex: 1,
        scale: true,
        min: 0,
        max: 100,
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: {
          ...REPORT_CHART_AXIS_LABEL_SM,
          formatter: (v) => fmtIndicator(v),
        },
        splitLine: REPORT_CHART_SPLIT_LINE,
      },
    ]
    : [{
      scale: true,
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: {
        ...REPORT_CHART_AXIS_LABEL_SM,
        formatter: (v) => fmtPrice(v),
      },
      splitLine: REPORT_CHART_SPLIT_LINE,
    }];

  return {
    animation: false,
    legend: legendItems.length
      ? {
        data: legendItems,
        top: 0,
        textStyle: { color: 'rgba(255,255,255,0.72)', fontSize: 11 },
        itemWidth: 14,
        itemHeight: 8,
      }
      : undefined,
    axisPointer: {
      link: hasOscillator ? [{ xAxisIndex: [0, 1] }] : undefined,
    },
    grid,
    graphic: hasOscillator ? buildPanelDividerGraphic() : undefined,
    dataZoom: [
      {
        type: 'slider',
        xAxisIndex: xZoomIndexes,
        filterMode: 'none',
        height: 22,
        bottom: 8,
        start: zoom.start,
        end: zoom.end,
        borderColor: 'rgba(255,255,255,0.12)',
        fillerColor: 'rgba(0, 188, 212, 0.15)',
        handleStyle: { color: '#4dd0e1' },
        textStyle: { color: 'rgba(255,255,255,0.55)', fontSize: 10 },
      },
    ],
    xAxis,
    yAxis,
    tooltip: {
      ...REPORT_CHART_TOOLTIP,
      trigger: 'axis',
      axisPointer: { type: 'cross' },
      formatter: (params) => {
        const arr = Array.isArray(params) ? params : [params];
        if (!arr.length) return '';
        const lines = [formatReportChartDateLabel(arr[0].axisValue)];
        const seenMarker = new Set();
        arr.forEach((p) => {
          const ohlc = readCandlestickOHLC(p, candleByDate, candleData);
          if (ohlc) {
            lines.push(
              `开盘 ${fmtPrice(ohlc.open)}　收盘 ${fmtPrice(ohlc.close)}　`
              + `最低 ${fmtPrice(ohlc.low)}　最高 ${fmtPrice(ohlc.high)}`,
            );
            return;
          }
          if (p.seriesType === 'scatter') {
            const meta = p.data?._markerMeta;
            const key = meta?.opportunity_id || meta?.date || p.seriesName;
            if (meta && !seenMarker.has(key)) {
              seenMarker.add(key);
              lines.push(formatMarkerTooltip(meta));
            }
            return;
          }
          if (p.seriesType === 'line' && p.value != null && Number.isFinite(Number(p.value))) {
            lines.push(`${p.seriesName}：${fmtIndicator(p.value)}`);
          }
        });
        return lines.filter(Boolean).join('<br/>');
      },
    },
    series: [
      {
        name: 'K线',
        type: 'candlestick',
        xAxisIndex: 0,
        yAxisIndex: 0,
        data: candleData,
        itemStyle: {
          color: CANDLE_UP_COLOR,
          color0: CANDLE_DOWN_COLOR,
          borderColor: CANDLE_UP_COLOR,
          borderColor0: CANDLE_DOWN_COLOR,
        },
      },
      ...overlayLineSeries,
      ...oscillatorLineSeries,
      ...markerSeries,
    ],
  };
}
